-- 2. sales mart tables (conformed keys; loaded by departments/sales with an atomic swap)

CREATE TABLE IF NOT EXISTS fact_sales_lines (
    `order_number` TEXT NULL,
    `order_date_date` DATE NULL,
    `order_date` DATETIME NULL,
    DateKey INT NOT NULL DEFAULT -1,
    CustomerKey BIGINT NOT NULL DEFAULT -1,
    `customer` TEXT NULL,
    `CustomerID` VARCHAR(255) NULL,
    `First_Purchase_Date` DATE NULL,
    `CustomerStatus` TEXT NULL,
    SalespersonKey INT NOT NULL DEFAULT -1,
    `salesperson` TEXT NULL,
    `sales_team` TEXT NULL,
    `sales_team_key` TEXT NULL,
    `sales_team_segment` TEXT NULL,
    `sales_team_city` TEXT NULL,
    `sales_team_status` TEXT NULL,
    `SalesTeam` TEXT NULL,
    SalesTeamKey VARCHAR(64) NOT NULL DEFAULT '-1',
    `SalesSegment` TEXT NULL,
    SegmentKey INT NOT NULL DEFAULT -1,
    `SalesCity` TEXT NULL,
    `SalesTeamStatus` TEXT NULL,
    `DistributionChannel` TEXT NULL,
    ChannelKey INT NOT NULL DEFAULT -1,
    `company_final` TEXT NULL,
    CompanyKey BIGINT NOT NULL DEFAULT -1,
    ProductMasterKey VARCHAR(191) NOT NULL DEFAULT '-1',
    `OdooProductID` BIGINT NULL,
    `OdooProductName` TEXT NULL,
    `OdooProductNameClean` TEXT NULL,
    `ProductJoinKey` VARCHAR(255) NULL,
    `ProductLevel` TEXT NULL,
    `SKU` TEXT NULL,
    `Size` TEXT NULL,
    `product_name_raw` TEXT NULL,
    `product_name_clean` TEXT NULL,
    `product_name` TEXT NULL,
    `ProductNameRaw` TEXT NULL,
    `ProductName` TEXT NULL,
    `ProductNameClean` TEXT NULL,
    `ProductMappingStatus` TEXT NULL,
    `ProductMappingReason` TEXT NULL,
    `ProductMatchKey` VARCHAR(255) NULL,
    `IsMappedProduct` TINYINT(1) NULL,
    `Category` TEXT NULL,
    `Brand` TEXT NULL,
    `SubBrand` TEXT NULL,
    `Family` TEXT NULL,
    `is_discount` TINYINT(1) NULL,
    `quantity` DECIMAL(20,6) NULL,
    `Volume` DECIMAL(20,6) NULL,
    `line_total` DECIMAL(20,6) NULL,
    `Value` DECIMAL(20,6) NULL,
    `untaxed_total` DECIMAL(20,6) NULL,
    `qty_ordered` DECIMAL(20,6) NULL,
    `qty_delivered` DECIMAL(20,6) NULL,
    `uom` TEXT NULL,
    `uom_id` BIGINT NULL,
    SaleReportLineID BIGINT NOT NULL,
    `OdooOrderID` BIGINT NULL,
    `OdooPartnerID` BIGINT NULL,
    `IsIntercompany` TINYINT(1) NULL,
    `invoice_status` TEXT NULL,
    `order_state` TEXT NULL,
    `InvoiceValue` DECIMAL(20,6) NULL,
    `Invoice Class` TEXT NULL,
    `InvoiceYear` BIGINT NULL,
    SalesOrderKey BIGINT NOT NULL DEFAULT -1,
    ProductKey BIGINT NOT NULL DEFAULT -1,
    _run_id CHAR(36) NULL COMMENT 'etl_run_log.run_uid of the load',
    PRIMARY KEY (SaleReportLineID),
    INDEX ix_fact_sales_lines_datekey (DateKey),
    INDEX ix_fact_sales_lines_customerkey (CustomerKey),
    INDEX ix_fact_sales_lines_salespersonkey (SalespersonKey),
    INDEX ix_fact_sales_lines_salesteamkey (SalesTeamKey),
    INDEX ix_fact_sales_lines_companykey (CompanyKey),
    INDEX ix_fact_sales_lines_productkey (ProductKey),
    INDEX ix_fact_sales_lines_productmasterkey (ProductMasterKey),
    INDEX ix_fact_sales_lines_salesorderkey (SalesOrderKey)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

