    `LeadCreationSource` TEXT NULL,
    `GeneratedLeadReason` TEXT NULL,
    `IsActiveLead` TINYINT(1) NULL,
    `IsConvertedToOpportunity` TINYINT(1) NULL,
    `OpportunityID` BIGINT NULL,
    `LeadAgeDays` FLOAT NULL,
    `Count` BIGINT NULL,
    _run_id CHAR(36) NULL COMMENT 'etl_run_log.run_uid of the load',
    PRIMARY KEY (LeadID, IsOdooCreatedLead, IsETLCreatedLead),
    INDEX ix_fact_sales_leads_leadcreateddatekey (LeadCreatedDateKey),
    INDEX ix_fact_sales_leads_salespersonkey (SalespersonKey),
    INDEX ix_fact_sales_leads_salesteamkey (SalesTeamKey),
    INDEX ix_fact_sales_leads_companykey (CompanyKey)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS fact_sales_opportunities (
    OpportunityID BIGINT NOT NULL,
    `LeadID` VARCHAR(255) NULL,
    `JourneyKey` VARCHAR(255) NULL,
    `PipelineRecordID` VARCHAR(255) NULL,
