    `IsActiveOpportunity` TINYINT(1) NULL,
    `IsWon` TINYINT(1) NULL,
    `IsLost` TINYINT(1) NULL,
    `IsOpen` TINYINT(1) NULL,
    `LostReason` TEXT NULL,
    `LostReasonID` BIGINT NULL,
    `Salesperson` TEXT NULL,
    `SalespersonID` BIGINT NULL,
    SalespersonKey INT NOT NULL DEFAULT -1,
    `SalesTeam` TEXT NULL,
    `SalesTeamID` BIGINT NULL,
    SalesTeamKey VARCHAR(64) NOT NULL DEFAULT '-1',
    `SalesSegment` TEXT NULL,
    SegmentKey INT NOT NULL DEFAULT -1,
    `Company` TEXT NULL,
    CompanyKey BIGINT NOT NULL DEFAULT -1,
    `Customer` TEXT NULL,
    `CustomerID` BIGINT NULL,
    CustomerKey BIGINT NOT NULL DEFAULT -1,
    `HasQuotation` TINYINT(1) NULL,
    `FirstQuotationDate` DATETIME NULL,
    FirstQuotationDateKey INT NOT NULL DEFAULT -1,
    `LastQuotationID` BIGINT NULL,
    `LastQuotationDate` DATETIME NULL,
    `LastQuotationValue` DECIMAL(20,6) NULL,
    `LastQuotationStatus` TEXT NULL,
    `DaysSinceLastQuotation` BIGINT NULL,
    `OpportunityAge` FLOAT NULL,
    `ActivityState` TEXT NULL,
    `NextActivityDate` DATETIME NULL,
    `HasNextStep` TINYINT(1) NULL,
    `HasRecentActivity` TINYINT(1) NULL,
    `IsInactive` TINYINT(1) NULL,
    `DaysSinceUpdate` FLOAT NULL,
    `Count` BIGINT NULL,
    _run_id CHAR(36) NULL COMMENT 'etl_run_log.run_uid of the load',
    PRIMARY KEY (OpportunityID),
    INDEX ix_fact_sales_opportunities_opportunitycreateddatekey (OpportunityCreatedDateKey),
    INDEX ix_fact_sales_opportunities_salespersonkey (SalespersonKey),
    INDEX ix_fact_sales_opportunities_salesteamkey (SalesTeamKey),
    INDEX ix_fact_sales_opportunities_companykey (CompanyKey)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS fact_sales_product_daily (
    `Company` TEXT NULL,
    CompanyKey BIGINT NOT NULL DEFAULT -1,
    `ProductMatchKey` VARCHAR(255) NULL,
    `OrderDate` DATE NULL,
    DateKey INT NOT NULL DEFAULT -1,
    SalespersonKey INT NOT NULL DEFAULT -1,
    SegmentKey INT NOT NULL DEFAULT -1,
    ChannelKey INT NOT NULL DEFAULT -1,
    SalesTeamKey VARCHAR(64) NOT NULL DEFAULT '-1',
    `IsIntercompany` TINYINT(1) NULL,
    `IsMappedProduct` TINYINT(1) NULL,
    `UoM` TEXT NULL,
    `Value` DECIMAL(20,6) NULL,
    `Qty` DECIMAL(20,6) NULL,
    `QtyOrdered` DECIMAL(20,6) NULL,
    `QtyDelivered` DECIMAL(20,6) NULL,
    `CostValue` DECIMAL(20,6) NULL,
    `CostedQty` DECIMAL(20,6) NULL,
    `UncostedQty` DECIMAL(20,6) NULL,
    `Lines` BIGINT NULL,
    row_key CHAR(40) NOT NULL COMMENT 'sha1 of the grain (date, company, product match key, salesperson, team, channel, segment, intercompany, uom)',
    _run_id CHAR(36) NULL COMMENT 'etl_run_log.run_uid of the load',
    PRIMARY KEY (row_key),
    INDEX ix_fact_sales_product_daily_datekey (DateKey),
    INDEX ix_fact_sales_product_daily_companykey (CompanyKey),
    INDEX ix_fact_sales_product_daily_salespersonkey (SalespersonKey),
    INDEX ix_fact_sales_product_daily_salesteamkey (SalesTeamKey)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS fact_sales_inventory_snapshot (
    `SnapshotDate` DATE NULL,
