) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 3. serving views (1:1 projections; the backend reads these, so physical marts can change without touching it)

CREATE OR REPLACE VIEW v_sales_lines AS SELECT * FROM fact_sales_lines;
CREATE OR REPLACE VIEW v_sales_orders AS SELECT * FROM fact_sales_orders;
CREATE OR REPLACE VIEW v_sales_documents AS SELECT * FROM fact_sales_documents;
CREATE OR REPLACE VIEW v_sales_targets AS SELECT * FROM fact_sales_targets;
CREATE OR REPLACE VIEW v_sales_deliveries AS SELECT * FROM fact_sales_deliveries;
CREATE OR REPLACE VIEW v_sales_leads AS SELECT * FROM fact_sales_leads;
CREATE OR REPLACE VIEW v_sales_opportunities AS SELECT * FROM fact_sales_opportunities;
CREATE OR REPLACE VIEW v_sales_product_daily AS SELECT * FROM fact_sales_product_daily;
CREATE OR REPLACE VIEW v_sales_inventory AS SELECT * FROM fact_sales_inventory_snapshot;
CREATE OR REPLACE VIEW v_sales_bcg_matrix AS SELECT * FROM fact_sales_bcg_matrix;
CREATE OR REPLACE VIEW v_sales_product_dashboard AS SELECT * FROM dim_sales_product_dashboard;
